CREATE TABLE IF NOT EXISTS roles (name VARCHAR(40) PRIMARY KEY);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(40) NOT NULL DEFAULT 'customer', created_at VARCHAR(30) NOT NULL, FOREIGN KEY(role) REFERENCES roles(name));
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT, slug VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, description TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS brands (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT, category_id INTEGER NOT NULL, brand_id INTEGER NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, name VARCHAR(220) NOT NULL, description TEXT NOT NULL, image VARCHAR(500) NOT NULL, specs TEXT NOT NULL, is_demo INTEGER NOT NULL DEFAULT 1, source_url VARCHAR(1000), active INTEGER NOT NULL DEFAULT 1, featured INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(brand_id) REFERENCES brands(id));
CREATE TABLE IF NOT EXISTS product_variants (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL, sku VARCHAR(100) NOT NULL UNIQUE, fincon_sku VARCHAR(100), label VARCHAR(120) NOT NULL DEFAULT 'Standard', price_cents BIGINT NOT NULL CHECK(price_cents>=0), dealer_price_cents BIGINT, old_price_cents BIGINT, stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0), attributes TEXT NOT NULL, stock_verified_at VARCHAR(30), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS product_images (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL, url VARCHAR(500) NOT NULL, alt VARCHAR(240) NOT NULL, position INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS customer_addresses (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, label VARCHAR(80), address TEXT NOT NULL, city VARCHAR(120) NOT NULL, postal_code VARCHAR(15) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS dealer_applications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE, business_name VARCHAR(200) NOT NULL, registration_number VARCHAR(120) NOT NULL, vat_number VARCHAR(120), contact_name VARCHAR(120) NOT NULL, phone VARCHAR(40) NOT NULL, address TEXT NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'pending', fincon_account VARCHAR(100), reviewed_by INTEGER, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS carts (id INTEGER PRIMARY KEY AUTOINCREMENT, token VARCHAR(64) NOT NULL UNIQUE, user_id INTEGER, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS cart_items (cart_id INTEGER NOT NULL, variant_id INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), PRIMARY KEY(cart_id,variant_id), FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE, FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT, number VARCHAR(50) NOT NULL UNIQUE, user_id INTEGER, guest_token VARCHAR(64), idempotency_key VARCHAR(100) NOT NULL UNIQUE, customer_snapshot TEXT NOT NULL, subtotal_cents BIGINT NOT NULL, shipping_cents BIGINT, total_cents BIGINT NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'pending_payment', payment_method VARCHAR(40) NOT NULL, delivery VARCHAR(40) NOT NULL, is_demo INTEGER NOT NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, variant_id INTEGER NOT NULL, sku VARCHAR(100) NOT NULL, name VARCHAR(220) NOT NULL, quantity INTEGER NOT NULL, unit_price_cents BIGINT NOT NULL, line_total_cents BIGINT NOT NULL, specifications TEXT NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, provider VARCHAR(40) NOT NULL, provider_reference VARCHAR(180) NOT NULL UNIQUE, amount_cents BIGINT NOT NULL, status VARCHAR(40) NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS payment_events (id INTEGER PRIMARY KEY AUTOINCREMENT, provider VARCHAR(40) NOT NULL, event_key VARCHAR(180) NOT NULL UNIQUE, order_id INTEGER, payload_hash VARCHAR(64) NOT NULL, result VARCHAR(40) NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS shipments (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, provider VARCHAR(40) NOT NULL, booking_key VARCHAR(100) NOT NULL UNIQUE, provider_reference VARCHAR(180), status VARCHAR(40) NOT NULL, details TEXT NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS shipment_events (id INTEGER PRIMARY KEY AUTOINCREMENT, shipment_id INTEGER NOT NULL, event_key VARCHAR(180) NOT NULL UNIQUE, status VARCHAR(40) NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(shipment_id) REFERENCES shipments(id));
CREATE TABLE IF NOT EXISTS quotes (id INTEGER PRIMARY KEY AUTOINCREMENT, number VARCHAR(50) NOT NULL UNIQUE, user_id INTEGER, guest_token VARCHAR(64), customer_snapshot TEXT NOT NULL, total_cents BIGINT NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'draft', expires_at VARCHAR(30) NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS quote_items (id INTEGER PRIMARY KEY AUTOINCREMENT, quote_id INTEGER NOT NULL, variant_id INTEGER NOT NULL, sku VARCHAR(100) NOT NULL, name VARCHAR(220) NOT NULL, quantity INTEGER NOT NULL, unit_price_cents BIGINT NOT NULL, line_total_cents BIGINT NOT NULL, FOREIGN KEY(quote_id) REFERENCES quotes(id), FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE IF NOT EXISTS pc_builds (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, share_token VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, purpose VARCHAR(80) NOT NULL, budget_cents BIGINT, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS pc_build_components (build_id INTEGER NOT NULL, component_type VARCHAR(40) NOT NULL, variant_id INTEGER NOT NULL, PRIMARY KEY(build_id,component_type), FOREIGN KEY(build_id) REFERENCES pc_builds(id) ON DELETE CASCADE, FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE IF NOT EXISTS wishlists (user_id INTEGER, guest_token VARCHAR(64) NOT NULL, product_id INTEGER NOT NULL, PRIMARY KEY(guest_token,product_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS support_tickets (id INTEGER PRIMARY KEY AUTOINCREMENT, number VARCHAR(50) NOT NULL UNIQUE, user_id INTEGER NOT NULL, subject VARCHAR(180) NOT NULL, category VARCHAR(80) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'open', priority VARCHAR(20) NOT NULL DEFAULT 'normal', assigned_to INTEGER, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(assigned_to) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS ticket_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, ticket_id INTEGER NOT NULL, user_id INTEGER NOT NULL, message TEXT NOT NULL, internal INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(ticket_id) REFERENCES support_tickets(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS marketing_consents (email VARCHAR(254) PRIMARY KEY, user_id INTEGER, consent INTEGER NOT NULL DEFAULT 0, source VARCHAR(80) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS email_campaigns (id INTEGER PRIMARY KEY AUTOINCREMENT, title VARCHAR(180) NOT NULL, subject VARCHAR(220) NOT NULL, body TEXT NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'draft', created_by INTEGER NOT NULL, scheduled_at VARCHAR(30), created_at VARCHAR(30) NOT NULL, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS email_outbox (id INTEGER PRIMARY KEY AUTOINCREMENT, recipient VARCHAR(254) NOT NULL, kind VARCHAR(80) NOT NULL, payload TEXT NOT NULL, dedupe_key VARCHAR(180) NOT NULL UNIQUE, status VARCHAR(40) NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS password_resets (token_hash VARCHAR(64) PRIMARY KEY, user_id INTEGER NOT NULL, expires_at VARCHAR(30) NOT NULL, used_at VARCHAR(30), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS rate_limits (bucket VARCHAR(180) PRIMARY KEY, hits INTEGER NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, variant_id INTEGER NOT NULL, stock INTEGER NOT NULL, source VARCHAR(40) NOT NULL, verified_at VARCHAR(30) NOT NULL, FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE IF NOT EXISTS integration_sync_jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, provider VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL, processed INTEGER NOT NULL DEFAULT 0, error TEXT, started_at VARCHAR(30) NOT NULL, finished_at VARCHAR(30));
CREATE TABLE IF NOT EXISTS admin_audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id INTEGER, action VARCHAR(120) NOT NULL, entity VARCHAR(120) NOT NULL, details TEXT NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS coupons (code VARCHAR(50) PRIMARY KEY, percent INTEGER NOT NULL CHECK(percent>=0 AND percent<=100), expires_at VARCHAR(30) NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id,active);
CREATE INDEX IF NOT EXISTS idx_products_brand ON products(brand_id,active);
CREATE INDEX IF NOT EXISTS idx_variants_product ON product_variants(product_id);
CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_orders_guest ON orders(guest_token);
CREATE INDEX IF NOT EXISTS idx_carts_updated ON carts(updated_at);
CREATE INDEX IF NOT EXISTS idx_tickets_user ON support_tickets(user_id,updated_at);
CREATE INDEX IF NOT EXISTS idx_outbox_status ON email_outbox(status,created_at);
CREATE TABLE IF NOT EXISTS cart_coupons (cart_id INTEGER PRIMARY KEY, code VARCHAR(50) NOT NULL, FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE, FOREIGN KEY(code) REFERENCES coupons(code));
